    const levels = extra.filter((l) => SORT_GETTERS[l.field]);
    if (!levels.length || !items || items.length < 2) return items;
    const all = [{ field: primary, desc: !primaryAsc }, ...levels].filter((l) => SORT_GETTERS[l.field]);
