      const o = fields[i];
      if (!o || o.type === "checkbox" || o.type === "range" || o.type === "radio" || o.type === "file" || !String(o.value || "").trim()) { c.remove(); return; }
      const span = document.createElement("span");
      span.textContent = o.value;
